  ],
  "track_plan": [
    {
      "id": "low_strings_pulse",
      "name": "Low Strings Pulse",
      "role": "bass pulse",
      "register": {
        "low": 28,
        "high": 55
      },
      "instrument_hint": "contrabasses, pizzicato/arco",
      "section_jobs": [
        {
          "section_id": "contained",
          "intent": "Lay down steady half-note and quarter-note pulse; leave space on beat 4",
          "density": "sparse"
        },
        {
          "section_id": "pressure",
          "intent": "Add off-beat accents and occasional syncopation to push momentum",
          "density": "medium"
        }
      ]
    },
    {
      "id": "viola_ostinato",
      "name": "Viola Ostinato",
      "role": "ostinato",
      "register": {
        "low": 48,
        "high": 72
      },
      "instrument_hint": "violas, non legato",
      "section_jobs": [
        {
          "section_id": "contained",
          "intent": "Repeating three-note figure with a rest gap; irregular accent on second sixteenth",
          "density": "medium"
        },
        {
          "section_id": "pressure",
          "intent": "Shift ostinato up a third and shorten gaps; add a passing chromatic note",
          "density": "dense"
        }
      ]
    },
    {
      "id": "cello_counterline",
      "name": "Cello Counterline",
      "role": "counterline",
      "register": {
        "low": 36,
        "high": 69
      },
      "instrument_hint": "cellos, lyrical",
      "section_jobs": [
        {
          "section_id": "contained",
          "intent": "Answer the ostinato with long notes and one stepwise descent",
          "density": "sparse"
        },
        {
          "section_id": "pressure",
          "intent": "Climb into tenor register and use dotted rhythm to create tension",
          "density": "medium"
        }
      ]
    },
    {
      "id": "muted_percussion",
      "name": "Muted Percussion",
      "role": "pulse/color",
      "register": {
        "low": 60,
        "high": 72
      },
      "instrument_hint": "timpani with cloth mallets, or woodblock",
      "section_jobs": [
        {
          "section_id": "contained",
          "intent": "Soft timpani on downbeats only; remain in background",
          "density": "sparse"
        },
        {
          "section_id": "pressure",
          "intent": "Add rhythmic punctuation on beat 2 and syncopated pickup to beat 4",
          "density": "medium"
        }
      ]
    }
  ],
  "motif_strategy": "Viola ostinato uses a short 3+2 pattern with rests on the last eighth; cello counterline decorates phrase endings while bass pulse anchors chord roots. Second section transposes the motif up a minor third and compresses rests to raise intensity without sixteenth-note walls.",
  "harmony_strategy": "D minor with alternating Dm and Bb/D implied by bass pulse; second section moves to Bb major and G minor, creating lift; avoid full triads in any single track to keep dialogue space.",
  "groove_strategy": "Steady half-note bass pulse in contained section, with octave accents on off-beats in pressure section; muted percussion marks structural downbeats and adds a dry woodblock pick-up only in bar 7-8."
}

